60		// PageSize picks the page length, 1..MaxPageSize; zero means
61		// DefaultPageSize. It may change between pages of the same query.
62		PageSize int
63		// Cursor continues an earlier query; empty asks for the first page. On
64		// continuation the height range and TxIDs must equal the first page's.
65		Cursor string
66	}
67	
68	// TxHit is one transaction occurrence on the main chain. The same
69	// identifier appears once per occurrence, in different blocks or several
70	// times inside one block.
