82		Hits []TxHit
83		// TotalMatches counts every matching occurrence in the pinned range; it
84		// does not change between pages of the same query.
85		TotalMatches int64
86		// MatchedBlocks counts the blocks holding at least one match.
87		MatchedBlocks int64
88		// ToHeight is the upper bound pinned by the first page: the requested
89		// To clamped to the chain tip seen at that moment.
