package indexroom

import (
	"errors"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"testing"
)

// This file pins the behavior that the snapshot's JSON text is a serialization,
// not a wire format with a fixed layout. The same legal snapshot written with
// reordered object fields, extra layout whitespace, or equivalent string
// escapes must restore the very same chain — same heights, hashes, parent
// links, and transaction order — while structural changes (a field written
// twice, the blocks array reversed) remain invalid, and the main chain is
// never touched by a rejected restore.

// uescape renders the code point r as a JSON \uXXXX escape (or the surrogate
// pair \uXXXX\uXXXX above the BMP) embedded in snapshot text.
func uescape(r rune) string {
	if r <= 0xFFFF {
		return fmt.Sprintf("\\u%04x", r)
	}
	r -= 0x10000
	high := 0xD800 + int(r>>10)
	low := 0xDC00 + int(r&0x3FF)
	return fmt.Sprintf("\\u%04x\\u%04x", high, low)
}

// prettyPrint re-renders canonical snapshot text with two-space indentation
// and a trailing newline, using the standard library so no production code is
// involved in manufacturing the "reshaped" input.
func prettyPrint(t *testing.T, canonical string) string {
	t.Helper()
	var buf strings.Builder
	if err := jsonIndent(&buf, canonical); err != nil {
		t.Fatalf("setup: indent snapshot failed: %v", err)
	}
	buf.WriteByte('\n')
	return buf.String()
}

// jsonIndent delegates to encoding/json's Indent; named separately so the
// testing file does not grow an encoding/json import for one call.
func jsonIndent(buf *strings.Builder, canonical string) error {
	var raw []byte
	dec := newJSONDecoder(canonical)
	if err := dec.Decode(&raw); err != nil {
		return err
	}
	return indentJSON(buf, raw)
}

// canonicalSnapshotDoc mirrors snapshotDoc without the timestamp RawMessage
// so hand-built tests can parse exports back generically.
type canonicalSnapshotDoc struct {
	Version int64 `json:"version"`
	Timestamp json.RawMessage `json:"timestamp,omitempty"`
}

// shuffledDoc is the hand-written reshaped snapshot used across these tests:

// shuffledV1Snapshot builds, in plain Go string surgery, a version-1 snapshot
// whose text departs from an export in every tolerated way:
//   - blocks precedes version at the top level;
//   - fields inside each block appear in an unusual order;
//   - the same identifiers are written partly as equivalent \uXXXX escapes
//     instead of literal characters;
//   - whitespace is added throughout (newlines, spaces inside the array).
func shuffledV1Snapshot() string {
	// Decoded identifiers: tx-中 at positions 0 and 2, the empty string at 3.
	return "{\n  \"blocks\" : [\n" +
		"    { \"txs\" : [ \"tx-" + uescape('中') + "\", \"other\", \"tx-中\", \"\" ],\n" +
		"      \"parent\" : \"" + uescape('g') + "enesis\", \"hash\" : \"" + uescape('h') + "1\", \"height\" : 1 },\n" +
		"    { \"parent\" : \"h" + uescape('1') + "\", \"txs\" : [ ], \"height\" : 2, \"hash\" : \"h2\" }\n" +
		"  ],\n  \"tip\" : 2,\n  \"version\" : 1\n}\n"
}

// shuffledV2Snapshot is the version-2 counterpart: fields reordered
// (timestamp before height, txs last), timestamps written in varying literal
// forms (null, 0, a value), and escaping on the first block's identifiers.
func shuffledV2Snapshot() string {
	return "{\n  \"tip\" : 2, \n" +
		"  \"blocks\" : [\n" +
		"    { \"timestamp\" : null, \"hash\" : \"" + uescape('h') + "1\", \"parent\" : \"g\", \"height\" : 1, \"txs\" : [\"a\", \"\"] },\n" +
		"    { \"height\" : 2, \"hash\" : \"h2\", \"parent\" : \"h" + uescape('1') + "\", \"txs\" : [\"b\"], \"timestamp\" : 0 }\n" +
		"  ],\n  \"version\" : 2\n}\n"
}

// requireSameChain fails unless both indexes describe the same main chain:
// tip, ByHash, and the ordered blocks (height, hash, parent, txs in order,
// and timestamp presence/value).
func requireSameChain(t *testing.T, got, want *Index) {
	t.Helper()
	if got.Tip != want.Tip {
		t.Fatalf("tip=%d, want %d", got.Tip, want.Tip)
	}
	if len(got.Blocks) != len(want.Blocks) || len(got.ByHash) != len(want.ByHash) {
		t.Fatalf("chain size: blocks=%d byHash=%d, want blocks=%d byHash=%d",
			len(got.Blocks), len(got.ByHash), len(want.Blocks), len(want.ByHash))
	}
	for h := int64(1); h <= want.Tip; h++ {
		g, ok := got.Blocks[h]
		if !ok {
			t.Fatalf("missing block at height %d after restore", h)
		}
		w := want.Blocks[h]
		if g.Height != w.Height || g.Hash != w.Hash || g.Parent != w.Parent {
			t.Fatalf("height %d: got %+v, want %+v", h, g, w)
		}
		if !reflect.DeepEqual(g.Txs, w.Txs) {
			t.Fatalf("height %d txs=%q, want %q", h, g.Txs, w.Txs)
		}
		if (g.Time == nil) != (w.Time == nil) || (g.Time != nil && *g.Time != *w.Time) {
			t.Fatalf("height %d time=%v, want %v", h, g.Time, w.Time)
		}
		if got.ByHash[w.Hash] != h {
			t.Fatalf("by-hash lookup for %q=%d, want %d", w.Hash, got.ByHash[w.Hash], h)
		}
	}
}

// requireTxStats queries id on index and checks hit positions, total
// occurrences, and matched-block count against the supplied expectations.
func requireTxStats(t *testing.T, index *Index, id string, wantPositions []TxHit, total, matchedBlocks int64) {
	t.Helper()
	page, err := index.QueryTxs(TxQuery{TxIDs: []string{id}})
	if err != nil {
		t.Fatalf("query %q failed: %v", id, err)
	}
	if !reflect.DeepEqual(page.Hits, wantPositions) {
		t.Fatalf("query %q hits=%+v, want %+v", id, page.Hits, wantPositions)
	}
	if page.TotalMatches != total || page.MatchedBlocks != matchedBlocks {
		t.Fatalf("query %q: total=%d blocks=%d, want total=%d blocks=%d",
			id, page.TotalMatches, page.MatchedBlocks, total, matchedBlocks)
	}
}

// buildReferenceChain appends the chain the hand-written reshaped snapshots
// are meant to decode to, through the ordinary Append interface rather than
// the parser under test.
func buildReferenceChain() *Index {
	index := New()
	mustAppend := func(height int64, hash, parent string, txs []string, time *int64) {
		if err := index.Append(Block{Height: height, Hash: hash, Parent: parent, Txs: txs, Time: time}); err != nil {
			panic(fmt.Sprintf("setup append at height %d: %v", height, err))
		}
	}
	mustAppend(1, "h1", "genesis", []string{"tx-中", "other", "tx-中", ""}, nil)
	mustAppend(2, "h2", "h1", nil, nil)
	return index
}

func TestRestoreReshapedV1TextMatchesCanonicalChain(t *testing.T) {
	input := shuffledV1Snapshot()
	index := New()
	if err := index.Restore(strings.NewReader(input)); err != nil {
		t.Fatalf("reshaped snapshot rejected: %v", err)
	}
	requireSameChain(t, index, buildReferenceChain())

	// Queries by the decoded identifier — the form a regular consumer uses —
	// find every occurrence: duplicated id at positions 0 and 2 of block 1,
	// the empty id at position 3, and "other" at position 1.
	requireTxStats(t, index, "tx-中", []TxHit{
		{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 0},
		{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 2},
	}, 2, 1)
	requireTxStats(t, index, "", []TxHit{
		{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
	}, 1, 1)
	requireTxStats(t, index, "other", []TxHit{
		{Height: 1, BlockHash: "h1", TxID: "other", Position: 1},
	}, 1, 1)

	// Case and whitespace inside the identifier are part of the identifier:
	// no text normalization merges them with the real one.
	requireTxStats(t, index, "tx-中X", nil, 0, 0)
	requireTxStats(t, index, " tx-中", nil, 0, 0)
	requireTxStats(t, index, "tx-中 ", nil, 0, 0)
	requireTxStats(t, index, "TX-中", nil, 0, 0)

	// No filtering: order is exactly the decoded order.
	page, err := index.QueryTxs(TxQuery{})
	if err != nil {
		t.Fatal(err)
	}
	wantAll := []TxHit{
		{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 0},
		{Height: 1, BlockHash: "h1", TxID: "other", Position: 1},
		{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 2},
		{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
	}
	if !reflect.DeepEqual(page.Hits, wantAll) {
		t.Fatalf("unfiltered hits=%+v, want %+v", page.Hits, wantAll)
	}
	if page.TotalMatches != 4 || page.MatchedBlocks != 1 {
		t.Fatalf("unfiltered totals=%d/%d, want 4/1", page.TotalMatches, page.MatchedBlocks)
	}
}

func TestRestoreCanonicalAndReshapedTextProduceSameReexport(t *testing.T) {
	reference := buildReferenceChain()
	canonical := exportString(t, reference)

	restoredCanonical := New()
	if err := restoredCanonical.Restore(strings.NewReader(canonical)); err != nil {
		t.Fatal(err)
	}
	canonicalAgain := exportString(t, restoredCanonical)

	restoredShuffled := New()
	if err := restoredShuffled.Restore(strings.NewReader(shuffledV1Snapshot())); err != nil {
		t.Fatalf("reshaped snapshot rejected: %v", err)
	}
	shuffledAgain := exportString(t, restoredShuffled)

	// Same data → identical canonical text, regardless of the input layout.
	// It matches the reference export rather than the hand-written bytes.
	if canonicalAgain != canonical || shuffledAgain != canonical {
		t.Fatalf("re-exports disagree on normalization:\nreference: %s\ncanonical: %s\nreshaped:  %s",
